import {readFile} from 'node:fs/promises';
import {atomic} from '../src/vault.mjs';

export function quickBounds(value,area){
  const width=Math.max(value.width,area.width),height=Math.min(value.height,area.height);
  const x=Number.isFinite(value.position?.x)?value.position.x:area.x+(area.width-width)/2;
  const y=Number.isFinite(value.position?.y)?value.position.y:area.y+(area.height-height)/2;
  return {width,height,x:Math.round(Math.max(area.x,Math.min(x,area.x+area.width-width))),y:Math.round(Math.max(area.y,Math.min(y,area.y+area.height-height)))};
}
export class QuickWindowSettings{
  constructor(file){this.file=file;this.value={width:460,height:680,position:null};this.queue=Promise.resolve();}
  async init(){
    try{const v=JSON.parse(await readFile(this.file,'utf8'));
      for(const [key,min] of [['width',340],['height',360]])if(Number.isInteger(v[key])&&v[key]>=min&&v[key]<=8000)this.value[key]=v[key];
      if(v.position&&['x','y'].every(k=>Number.isFinite(v.position[k])&&Math.abs(v.position[k])<100000))this.value.position={x:v.position.x,y:v.position.y,monitor:String(v.position.monitor||'').slice(0,100)};
    }catch(e){if(e.code!=='ENOENT'&&!(e instanceof SyntaxError))throw e;}
  }
  async remember(bounds,monitor=''){
    const next={width:Math.round(bounds.width),height:Math.round(bounds.height),position:{x:Math.round(bounds.x),y:Math.round(bounds.y),monitor}};
    if(JSON.stringify(next)===JSON.stringify(this.value))return;
    this.value=next;const content=JSON.stringify(next);
    const job=this.queue.then(()=>atomic(this.file,content));this.queue=job.catch(()=>{});await job;
  }
}

import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
const run=promisify(execFile);
export const hyprland=!!(process.env.WAYLAND_DISPLAY&&process.env.HYPRLAND_INSTANCE_SIGNATURE);

export function monitorArea(m){
  const rotated=m.transform%2===1;
  const width=Math.round((rotated?m.height:m.width)/m.scale),height=Math.round((rotated?m.width:m.height)/m.scale);
  const [left,top,right,bottom]=m.reserved||[0,0,0,0];
  return {x:m.x+left,y:m.y+top,width:width+left+right,height:height-top-bottom};
}
export async function desktopWindow(title){
  const {stdout}=await run('hyprctl',['clients','-j'],{timeout:1500,maxBuffer:1024*1024});
  const client=JSON.parse(stdout).find(c=>c.pid===process.pid&&c.title===title&&c.floating);
  if(!client||!/^0x[0-9a-f]+$/i.test(client.address))return null;
  const {stdout:monitors}=await run('hyprctl',['monitors','-j'],{timeout:1500,maxBuffer:1024*1024});
  const displays=JSON.parse(monitors),monitor=displays.find(m=>m.id===client.monitor);
  if(!monitor)return null;
  return {client,monitor,displays,bounds:{x:client.at[0],y:client.at[1],width:client.size[0],height:client.size[1]}};
}
export async function placeDesktopWindow(client,title,{x,y,width,height}){
  // An address alone can be recycled. Check our PID and exact title again in the compositor.
  const code=`local w=hl.get_window("address:${client.address}"); if w and w.pid==${process.pid} and w.title==${JSON.stringify(title)} then hl.dispatch(hl.dsp.window.resize({x=${width},y=${height},window=w})); hl.dispatch(hl.dsp.window.move({x=${x},y=${y},window=w})); end`;
  await run('hyprctl',['eval',code],{timeout:1500,maxBuffer:16384});
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtemp,rm,writeFile} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {QuickWindowSettings,quickBounds} from '../desktop/quick-window.mjs';
import {monitorArea} from '../desktop/placement.mjs';

test('Quick ask restores independent geometry and clamps it after a monitor disappears',async t=>{
  const dir=await mkdtemp(join(tmpdir(),'aurora-quick-layout-'));t.after(()=>rm(dir,{recursive:true,force:true}));
  const file=join(dir,'quick-window.json'),settings=new QuickWindowSettings(file);await settings.init();
  await settings.remember({x:2040,y:-900,width:700,height:900},'external');
  const restarted=new QuickWindowSettings(file);await restarted.init();assert.deepEqual(restarted.value,settings.value);
  const area={x:-1280,y:30,width:1280,height:690};assert.deepEqual(quickBounds(restarted.value,area),{x:-700,y:30,width:700,height:690});
  await writeFile(file,JSON.stringify({width:99999,height:-12,position:{x:'wrong',y:0}}));
  const invalid=new QuickWindowSettings(file);await invalid.init();assert.deepEqual(invalid.value,{width:460,height:680,position:null});
});
test('placement uses scaled, rotated monitor work areas and fits small screens',()=>{
  const area=monitorArea({x:-1000,y:0,width:1920,height:1080,scale:1.5,transform:1,reserved:[10,30,10,20]});
  assert.deepEqual(area,{x:-990,y:30,width:700,height:1230});
  assert.deepEqual(quickBounds({width:460,height:680,position:null},{x:0,y:0,width:320,height:350}),{x:0,y:0,width:320,height:350});
});

